import{_ as r,a as e,c as a,ac as o}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解 · 33 遯：退避也需要判断至35 晋：被看见之后如何进取","description":"逐卦核读《周易》与《周易正义》，从退进之际读到家人分歧、遇险知止与解难。","frontmatter":{"title":"六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解 · 33 遯：退避也需要判断至35 晋：被看见之后如何进取","description":"逐卦核读《周易》与《周易正义》，从退进之际读到家人分歧、遇险知止与解难。","splitFrom":"life/personal/yijing/hexagrams-33-40.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解","summary":"逐卦核读《周易》与《周易正义》，从退进之际读到家人分歧、遇险知止与解难。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解","link":"/life/personal/yijing/hexagrams-33-40"},"next":{"text":"六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解 · 36 明夷：受伤的光明如何保存至38 睽：差异不必变成敌意","link":"/life/personal/yijing/hexagrams-33-40-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解","link":"/life/personal/yijing/hexagrams-33-40"},"next":{"text":"六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解 · 36 明夷：受伤的光明如何保存至38 睽：差异不必变成敌意","link":"/life/personal/yijing/hexagrams-33-40-part-02"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-33-40-part-01.md","filePath":"life/personal/yijing/hexagrams-33-40-part-01.md"}'),n={name:"life/personal/yijing/hexagrams-33-40-part-01.md"};function d(s,t,i,p,g,l){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="六十四卦详读-三十三至四十-遯、大壮、晋、明夷、家人、睽、蹇、解-·-33-遯-退避也需要判断至35-晋-被看见之后如何进取" tabindex="-1">六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解 · 33 遯：退避也需要判断至35 晋：被看见之后如何进取 <a class="header-anchor" href="#六十四卦详读-三十三至四十-遯、大壮、晋、明夷、家人、睽、蹇、解-·-33-遯-退避也需要判断至35-晋-被看见之后如何进取" aria-label="Permalink to &quot;六十四卦详读（三十三至四十）：遯、大壮、晋、明夷、家人、睽、蹇、解 · 33 遯：退避也需要判断至35 晋：被看见之后如何进取&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-33-40">返回分篇目录</a></p><p>本篇将经文、传文与现代概括分开：<strong>卦辞、爻辞</strong>是《周易》经文，<strong>大象</strong>出自《象传》；表中解释和“读法”是依据原文及古注所作的现代概括。爻从下向上读，初爻并不必然代表某个年龄，上爻也不是固定的结局。古注采用王弼注、孔颖达疏《周易正义》，它是重要的解释传统，不是经文的唯一可能含义。所引古籍为公有领域文本；电子本中的异体字、断句仍须留意。</p><p>这一组可成对比较：遯与大壮讨论退与强，晋与明夷讨论光明的显与藏，家人与睽讨论共同生活与分歧，蹇与解讨论困阻与舒解。“吉凶”保留为古代占筮判断，不作现实事件的科学预测。</p><h2 id="六十四卦详读-三十三至四十" tabindex="-1">六十四卦详读（三十三至四十） <a class="header-anchor" href="#六十四卦详读-三十三至四十" aria-label="Permalink to &quot;六十四卦详读（三十三至四十） {#六十四卦详读-三十三至四十}&quot;">​</a></h2><p>本篇将经文、传文与现代概括分开：<strong>卦辞、爻辞</strong>是《周易》经文，<strong>大象</strong>出自《象传》；表中解释和“读法”是依据原文及古注所作的现代概括。爻从下向上读，初爻并不必然代表某个年龄，上爻也不是固定的结局。古注采用王弼注、孔颖达疏《周易正义》，它是重要的解释传统，不是经文的唯一可能含义。所引古籍为公有领域文本；电子本中的异体字、断句仍须留意。</p><p>这一组可成对比较：遯与大壮讨论退与强，晋与明夷讨论光明的显与藏，家人与睽讨论共同生活与分歧，蹇与解讨论困阻与舒解。“吉凶”保留为古代占筮判断，不作现实事件的科学预测。</p><h2 id="gua-33" tabindex="-1">33 遯：退避也需要判断 <a class="header-anchor" href="#gua-33" aria-label="Permalink to &quot;33 遯：退避也需要判断 {#gua-33}&quot;">​</a></h2><p><strong>卦符：䷠｜上卦乾 ☰（天），下卦艮 ☶（山）。</strong>“遯”读 dùn，通行简体也写作“遁”。山在天下，所取不是逃跑速度，而是距离与止进之间的关系。</p><p><strong>卦辞原文：</strong></p><blockquote><p>遯：亨。小利貞。</p></blockquote><p><strong>白话概括：</strong> 退避可以获得通达，但仍须把握正当的分寸。《正义》把背景解释为阴渐长、阳渐退，以君子避开不利的政治环境说明“遯而亨”。这是古注的伦理象征，不能据此把阴或女性等同于坏人。“小利贞”的“小”有不同解释；本篇依古注说明为退势初起时仍有守正的余地，不把它换算成利益大小。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六</td><td>遯尾，厲，勿用有攸往。</td><td>落在退避队伍的尾端，处境危险；此时冒进反会扩大风险，先停止不合时宜的行动。</td></tr><tr><td>六二</td><td>執之用黃牛之革，莫之勝說。</td><td>如用坚韧牛革牢牢维系，无法解脱。“说”读为脱；《小象》着重“固志”，不是教人以拘禁解决关系。</td></tr><tr><td>九三</td><td>係遯，有疾厲，畜臣妾吉。</td><td>想退却有所牵系，因而疲困危险；古代家内事务尚可维持，大事却难担当，不能只摘出“吉”字。</td></tr><tr><td>九四</td><td>好遯君子吉，小人否。</td><td>与所爱有所割舍而能退，古注认为君子可以做到，小人受牵累；“好”有亲好之意，并非喜欢逃避。</td></tr><tr><td>九五</td><td>嘉遯，貞吉。</td><td>退得适宜而有节度，以正确志向为前提；不是一切放弃都值得赞美。</td></tr><tr><td>上九</td><td>肥遯，无不利。</td><td>“肥”在古注中指宽裕自得：牵累已远，退避从容；不是身体肥胖的占验。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>天下有山，遯；君子以遠小人，不惡而嚴。</p></blockquote><p><strong>大象解释：</strong> 保持距离，同时保有严正边界，不必用仇恨和争斗证明立场。“不恶而严”使退避包含自制，不只是远离。</p><p><strong>整体读法与误区：</strong> 六爻可比较“退得太迟—有所牵系—能够从容”的处境差别，却不必硬排为每个人必经的六阶段。今天可借它反思退出争执或不合适的合作：是否看清形势，是否履行仍有的责任，是否只是回避困难。这里是阅读应用，不是由卦证明某个人是“小人”。</p><p><strong>经传对读：</strong> 九三说“畜臣妾吉”，《小象》立刻补上“不可大事”；吉只适用于有限事务，不是整个人生都顺遂。九五的“正志”与上九的“无所疑”，则把可取的退避从单纯撤离转向志向清楚。读这三处，可以练习为占辞补回对象、条件和适用范围，也能理解为什么退去之后仍有小范围责任需要维持。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%81%AF" target="_blank" rel="noopener noreferrer">《周易·遯》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/04%E9%81%AF" target="_blank" rel="noopener noreferrer">《周易正义》卷四·遯</a>。</p><h2 id="gua-34" tabindex="-1">34 大壮：力量有边界 <a class="header-anchor" href="#gua-34" aria-label="Permalink to &quot;34 大壮：力量有边界 {#gua-34}&quot;">​</a></h2><p><strong>卦符：䷡｜上卦震 ☳（雷），下卦乾 ☰（天）。</strong> 乾的刚健与震的行动相合，显示力量增长；“壮”描述势能，并不自动等于行动正确。</p><p><strong>卦辞原文：</strong></p><blockquote><p>大壯：利貞。</p></blockquote><p><strong>白话概括：</strong> 力量强盛时，利于守正。《正义》以四阳渐长解释“大者壮”，同时将“正大”作为使用力量的条件。卦辞正文只有“利贞”两字，读者尤其应避免自行补成“任何竞争都会胜利”。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九</td><td>壯于趾，征凶，有孚。</td><td>力量先表现为脚趾急着向前，贸然出征有凶。“有孚”在此不能机械译成“诚信就吉”。</td></tr><tr><td>九二</td><td>貞吉。</td><td>处在刚强增长之中而能保持中道，古注据此说明其吉；短句的条件仍是“贞”。</td></tr><tr><td>九三</td><td>小人用壯，君子用罔，貞厲。羝羊觸藩，羸其角。</td><td>公羊撞篱，角反被缠住；“罔”的训释有分歧，整段明确警惕恃强冲撞，不能断章鼓励强攻。</td></tr><tr><td>九四</td><td>貞吉悔亡，藩決不羸，壯于大輿之輹。</td><td>篱障打开而不再受缠，力量像车下承重部件一样用在支撑上；本句据古注常用字“輿、輹”录。</td></tr><tr><td>六五</td><td>喪羊于易，无悔。</td><td>在平易之处失去羊，古注借此说放下强狠而免悔；“易”也有场所等解释，不据一字推定地理位置。</td></tr><tr><td>上六</td><td>羝羊觸藩，不能退，不能遂，无攸利，艱則吉。</td><td>进退两难，继续蛮干无利；承认困难、谨慎处置，才有改善可能。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>雷在天上，大壯；君子以非禮弗履。</p></blockquote><p><strong>大象解释：</strong> 雷声强大，却引出“不做不合礼的事”。力量越充足，越应检查行为是否越界；“礼”首先属于古代规范，现代应用须另行论证其合理性。</p><p><strong>整体读法与误区：</strong> 本卦反复出现羊角和篱笆，制造的是“力越用越被困”的反讽。可与遯比较：退不必是怯懦，强也不必表现为冲撞。今天谈权力、资源或体力时，可问其使用是否有规则和承重基础；不能用“正大”包装自身所有愿望。电子本九四“轝／輿、腹／輹”有异文，读象时以车体支撑义说明，不掩盖文本差别。</p><p><strong>经传对读：</strong> 初九、九三和上六都写身体末端或羊角，九四却写车体下的支撑：力量从向前顶撞转为承载，意象已经发生变化。九二仅两字“贞吉”，《小象》用“以中”说明理由；可见文字较短不意味着条件较少。读时应把这些解释关系列出来，再判断“壮”究竟用在何处。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E5%A3%AF" target="_blank" rel="noopener noreferrer">《周易·大壮》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/04%E5%A4%A7%E5%A3%AF" target="_blank" rel="noopener noreferrer">《周易正义》卷四·大壮</a>。</p><h2 id="gua-35" tabindex="-1">35 晋：被看见之后如何进取 <a class="header-anchor" href="#gua-35" aria-label="Permalink to &quot;35 晋：被看见之后如何进取 {#gua-35}&quot;">​</a></h2><p><strong>卦符：䷢｜上卦离 ☲（火、明），下卦坤 ☷（地）。</strong> 光明出于地上，形成“进”的意象；与下一卦明入地中的明夷相对。</p><p><strong>卦辞原文：</strong></p><blockquote><p>晉：康侯用錫馬蕃庶，晝日三接。</p></blockquote><p><strong>白话概括：</strong> 受到嘉许的诸侯获赐众多马匹，一天中多次受到接见。《正义》将“康”释作美，把这一画面解释为臣子受到君主厚遇。它保留了古代封建政治的礼遇场景，不等同于现代职位升迁指南；“三”也不宜直接折算成三个工作日。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六</td><td>晉如，摧如，貞吉。罔孚，裕无咎。</td><td>前进又受阻，尚未获得信任；保持正当与宽裕态度，不必急于用激烈行动求认可。</td></tr><tr><td>六二</td><td>晉如，愁如，貞吉。受茲介福，于其王母。</td><td>进而忧虑，守正仍吉；“王母”保留尊贵女性或祖母的古代语境，不混同后来的神仙信仰。</td></tr><tr><td>六三</td><td>眾允，悔亡。</td><td>获得众人认可，原有的悔恨消除；这里重视共同信任，不能因此认定多数意见永远正确。</td></tr><tr><td>九四</td><td>晉如鼫鼠，貞厲。</td><td>进得像鼫鼠，古注用于批评贪据、不安其位；“鼫／硕”有异文，中心在不当占据造成危险。</td></tr><tr><td>六五</td><td>悔亡，矢得勿恤，往吉无不利。</td><td>不被得失焦虑牵制而前行。“矢”有作“失”者，通常按得失相对理解，仍须结合本爻处境。</td></tr><tr><td>上九</td><td>晉其角，維用伐邑，厲吉无咎，貞吝。</td><td>进到以角触物的程度，只在有限的整治情境中勉强可用；长久依赖强硬会有吝。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>明出地上，晉；君子以自昭明德。</p></blockquote><p><strong>大象解释：</strong> 把光明显现转为自身德行的澄明。受赏识是外在处境，“自昭”则是自己应做的事，两者不能互相替代。</p><p><strong>整体读法与误区：</strong> 全卦同时写到被信任、忧虑、群众认可、贪据与强进，说明“晋”不是一路上升的赞歌。值得比较初六的“罔孚”与六三的“众允”：信任需要形成的过程。今日可用来审视“被看见”是否建立在实际责任上，但不能从一卦推出升职日期、贵人身份或收入数额。上九的限制尤其提醒，受到认可也不意味着可以无限扩大权力。</p><p><strong>经传对读：</strong> 六二的忧愁没有直接变成凶，九四貌似正在前进却有厉，情绪感受与占断并不总一致。六五的“勿恤”也要放在前面多次受阻、求信的铺垫之后。大象把目光转回自身明德，提醒外界接见与赏赐之外，仍有不依赖他人评价的修养任务；这比把晋单独翻成升迁更完整。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%99%89" target="_blank" rel="noopener noreferrer">《周易·晋》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/04%E6%99%89" target="_blank" rel="noopener noreferrer">《周易正义》卷四·晋</a>。</p>',46)])])}const u=r(n,[["render",d]]);export{c as __pageData,u as default};
